// Real LiveConnect payload: {chat, inputs, userInput, intent}
const raw = $input.first().json;
const body = raw.body ?? raw;
const chat = body.chat ?? {};
const inputs = body.inputs ?? {};
const message = String(body.userInput || inputs.mensaje_inicial || '').trim();

return [{
	json: {
		message,
		conversationId: String(chat.id ?? ''),
		channelId: chat.id_canal ?? null,
		contactId: chat.contacto?.id ?? null,
		contactName: chat.contacto?.nombre || 'Customer',
		contactPhone: chat.contacto?.celular || inputs.celular || '',
	},
}];
